    "v13": "pkt",
    "v16": "tx_channel",
    "v12": "pkt_len",
    "v17": "next_desc",
    "v9": "tx_busy"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "tx_state head/first packet pointer"
    },
    {
      "offset": 4,
      "meaning": "tx_state packet count"
    },
    {
      "offset": 8,
      "meaning": "tx_state tail/last packet pointer"
    },
    {
      "offset": 12,
      "meaning": "tx_state accumulated length/timestamp"
    },
    {
      "offset": 32,
      "meaning": "tx_state busy/enqueue flag"
    }
  ]
